-- Lua 5.4 / LuaJIT differential of *mutated* shared ArrayBuffer views.
-- Expectations generated by pinned DragonBonesJS, never copied into code.
package.path="./?.lua;./?/init.lua;"..package.path
local Object=require("dragonbones.original.parser.ObjectDataParser")
local Binary=require("dragonbones.original.parser.BinaryDataParser")
local Data=require("dragonbones.original.model.DragonBonesData")
local path=arg[1] or "artifacts/upstream/shared_binary_expected.tsv"
local keys={"intArray","floatArray","frameIntArray","frameFloatArray",
  "frameArray","timelineArray","colorArray"}
local input={
  {"object-int-wrap","object","intArray",1,65535},
  {"object-int-negative","object","intArray",2,-32769},
  {"object-float-round","object","floatArray",1,0.1},
  {"object-frame-int","object","frameIntArray",1,65535},
  {"object-frame-float","object","frameFloatArray",1,-0.0},
  {"object-frame","object","frameArray",2,-30000},
  {"object-timeline","object","timelineArray",1,-1},
  {"object-color","object","colorArray",2,40000},
  {"binary-int-wrap","binary","intArray",1,65535},
  {"binary-float-round","binary","floatArray",2,0.1},
  {"binary-frame-int","binary","frameIntArray",2,-40000},
  {"binary-frame-float","binary","frameFloatArray",1,-0.0},
  {"binary-frame","binary","frameArray",1,42},
  {"binary-timeline","binary","timelineArray",2,-1},
  {"binary-color","binary","colorArray",1,-32769},
  {"alias-int","alias","intArray",1,-1},
  {"alias-color","alias","colorArray",2,32768},
  {"overlap-int","overlap","intArray",2,16256},
  {"overlap-float","overlap","floatArray",1,1.0},
}
local function setup(kind)
  local data=Data.new()
  if kind=="object" then
    local p=Object.new()
    p._data=data
    p._intArray={1,2}
    p._floatArray={0.5}
    p._frameIntArray={3,4}
    p._frameFloatArray={-1}
    p._frameArray={5,6}
    p._timelineArray={7,8}
    p._colorArray={9,10}
    p:_modifyArray()
  else
    local p=Binary.new()
    p._data=data
    p._binary=string.rep("\0",36)
    p._binaryOffset=0
    local offsets=kind=="overlap" and
      {0,8,0,8,16,4,20,4,24,4,28,4,32,4}
      or {0,8,8,8,16,4,20,4,24,4,28,4,32,kind=="alias" and 0 or 4}
    p:_parseArray({offset=offsets})
  end
  return data
end
local function hex(bytes)
  return (bytes:gsub(".",function(c)return ("%02x"):format(c:byte()) end))
end
local function split(s,sep)
  local result={}
  for token in (s..sep):gmatch("(.-)"..sep) do
    result[#result+1]=token
  end
  return result
end
local function near(raw,actual,name,key,i)
  assert(type(actual)=="number",name.."/"..key.." missing element "..i)
  if raw=="NaN" then assert(actual~=actual,name.." expected NaN")
  elseif raw=="Infinity" then assert(actual==math.huge)
  elseif raw=="-Infinity" then assert(actual==-math.huge)
  elseif raw=="-0" then assert(actual==0 and 1/actual==-math.huge)
  else
    local n=assert(tonumber(raw),"Invalid upstream number "..raw)
    local delta=math.abs(actual-n)
    assert(delta<=1e-7*math.max(1,math.abs(n),math.abs(actual)),
      ("%s %s[%d] Lua %.17g vs JS %.17g"):format(name,key,i,actual,n))
  end
end
local f=assert(io.open(path,"r"))
for _,spec in ipairs(input) do
  local name,kind,key,index,value=spec[1],spec[2],spec[3],spec[4],spec[5]
  local data=setup(kind)
  data[key][index]=value
  local row=assert(f:read("*l"),"Missing upstream expected row "..name)
  local fields=split(row,"\t")
  assert(fields[1]==name,"Unexpected upstream reference "..fields[1])
  assert(hex(data.binary)==fields[2],
    ("%s bytes Lua %s vs original %s"):format(name,hex(data.binary),fields[2]))
  local alias=data.intArray==data.colorArray and "alias" or "separate"
  assert(alias==fields[3],name.." alias mismatch")
  for k,viewKey in ipairs(keys) do
    local expected=fields[k+3]=="" and {} or split(fields[k+3],",")
    local actual=data[viewKey]
    assert(#actual==#expected,
      ("%s/%s Lua length %d vs JS %d"):format(name,viewKey,#actual,#expected))
    for i,raw in ipairs(expected) do near(raw,actual[i],name,viewKey,i) end
  end
end
assert(f:read("*l")==nil,"Extra original rows")
f:close()
print(("Pinned DragonBonesJS shared ArrayBuffer mutation: %d passed, 0 failed")
  :format(#input))
